"""ssw -- keyed spread-spectrum sample watermark (copy detection + per-licensee fingerprint).

Embed: x'_i = x_i + a_i * w_i,  w_i = keyed +/-1 stream at the row's address, a_i = alpha * local noise scale
(optionally capped by a per-sensor absolute tolerance).
Detect (blind, key only): r = winsorised high-pass residual of the suspect; T = sum(r_i w_i) / sqrt(sum r_i^2).
Under H0 (wrong key / unmarked data) w is independent of r, so T is ~N(0,1) *whatever the data's
autocorrelation is* -- the p-value needs no calibration. Invariant to affine rescaling (unit conversion).
"""
from __future__ import annotations

import numpy as np
import pandas as pd
from scipy.signal import correlate
from ..addressing import AddressSpec, compute_address
from ..prf import domain_id, prf_sign
from ._stats import loo_residual, local_scale, robust_scale, winsorize, z_to_p, stouffer


NAME = "ssw"


def markable_columns(df: pd.DataFrame, exclude: set[str], max_atom: float = 0.05) -> list[str]:
    """Float columns, minus atom-heavy ones: if one value covers > `max_atom` of the rows (sample-and-hold,
    saturation, a coarse ADC), additive marks would split the atom -- visible, and it breaks the marginal
    distribution (measured on SKAB's flow sensor: 22 % of rows at one value). Mark those with evt or not at all."""
    out = []
    for c in df.columns:
        if c in exclude or not pd.api.types.is_float_dtype(df[c]):
            continue
        vc = df[c].value_counts(normalize=True, dropna=True)
        if len(vc) and vc.iloc[0] > max_atom:
            continue
        out.append(c)
    return out


def embed(df: pd.DataFrame, key: bytes, addr: AddressSpec, columns: list[str], alpha: float = 0.1,
          tol: dict | None = None, k: int = 3, floor: float = 0.1, decimals: dict | None = None):
    out = df.copy()
    address = compute_address(df, addr)
    order = np.argsort(address, kind="stable")
    info = {}
    for c in columns:
        x = df[c].to_numpy(dtype=np.float64)
        ok = np.isfinite(x)
        xs = x[order]
        r = loo_residual(np.where(ok[order], xs, np.nanmedian(x)), k)
        g = robust_scale(r)
        if g == 0:
            info[c] = {"skipped": "constant channel"}
            continue
        a = alpha * np.maximum(local_scale(r), floor * g)
        if tol and c in tol:
            a = np.minimum(a, tol[c])
        w = prf_sign(key, domain_id("ssw:" + c), address[order])
        delta = np.zeros_like(x)
        delta[order] = np.where(ok[order], a * w, 0.0)
        y = x + delta
        if decimals and c in decimals:
            y = np.where(ok, np.round(y, decimals[c]), y)
        out[c] = y.astype(df[c].dtype)
        e = out[c].to_numpy(np.float64) - x
        info[c] = {"rmse_over_scale": float(np.sqrt(np.mean(e[ok] ** 2)) / g), "max_abs_err": float(np.abs(e[ok]).max())}
    return out, info


def _stat_column(x, address, key, c, k, max_shift, time_shift=0):
    ok = np.isfinite(x)
    x, address = x[ok], address[ok]
    if x.size < 32:
        return None
    order = np.argsort(address, kind="stable")
    xs, ad = x[order], address[order]
    r = winsorize(loo_residual(xs, k))
    den = float(np.sqrt(np.sum(r * r)))
    if den == 0:
        return None
    dom = domain_id("ssw:" + c)
    if time_shift:
        # timestamp addressing: the copy may have re-stamped every row by a constant offset (clock change, a
        # deliberate +1 s). z for every offset in [-time_shift, time_shift] ticks; detect() picks ONE offset shared
        # by all columns. zz[j] corresponds to the copy being (time_shift - j) ticks ahead of the release.
        zz = np.array([np.sum(r * prf_sign(key, dom, ad + s_)) for s_ in range(-time_shift, time_shift + 1)]) / den
        return {"zz": zz[::-1], "n": int(ad.size)}          # reversed: index i <-> copy ahead by (i - time_shift)
    if max_shift:
        n = ad.size
        w = prf_sign(key, dom, np.arange(-max_shift, n + max_shift, dtype=np.int64))
        cc = correlate(w, r, mode="valid", method="fft")  # length 2*max_shift+1, index j <-> row offset j - max_shift
        return {"zz": cc / den, "n": int(n)}
    w = prf_sign(key, dom, ad)
    return {"z": float(np.sum(r * w) / den), "n": int(ad.size), "shift": 0, "tests": 1}


def detect(df: pd.DataFrame, key: bytes, addr: AddressSpec, columns: list[str], k: int = 3,
           max_shift: int = 0, **_):
    time_shift = 0
    if max_shift and addr.kind != "position":
        # position: cross-correlate over row offsets; time: shift the tick address; keys: no meaningful offset
        time_shift, max_shift = (max_shift if addr.kind == "time" else 0), 0
    address = compute_address(df, addr)
    per, zs, zzs = {}, [], {}
    for c in columns:
        if c not in df.columns:
            per[c] = {"missing": True}
            continue
        s = _stat_column(df[c].to_numpy(dtype=np.float64), address, key, c, k, max_shift, time_shift)
        if s is None:
            per[c] = {"skipped": True}
            continue
        if "zz" in s:
            zzs[c] = s.pop("zz")
        else:
            s["p"] = z_to_p(s["z"])
            zs.append(s["z"])
        per[c] = s
    S = max_shift or time_shift
    if zzs:
        # ONE offset for all columns (a re-stamped or cropped copy moves every column together): Stouffer across
        # columns at each offset, best offset, Bonferroni over the 2S+1 offsets tried
        Z = np.vstack(list(zzs.values())).sum(0) / np.sqrt(len(zzs))
        j = int(np.argmax(Z))
        for c, zz in zzs.items():
            per[c].update({"z": float(zz[j]), "shift": j - S, "tests": 2 * S + 1})
        z = float(Z[j])
        return {"method": NAME, "columns": per, "z": z, "p": min(1.0, z_to_p(z) * (2 * S + 1)), "shift": j - S,
                "offsets_tested": 2 * S + 1,
                # combined z at every offset (index i <-> offset i - S): lets a caller holding many files search
                # one offset shared by all of them (sum across files, one Bonferroni) instead of one per file
                "z_by_offset": [float(v) for v in Z]}
    if not zs:
        return {"method": NAME, "columns": per, "z": 0.0, "p": 1.0}
    z = stouffer(zs)
    return {"method": NAME, "columns": per, "z": z, "p": min(1.0, z_to_p(z))}
